class Tag { String tag() { return "A"; } }
class ChildTag extends Tag {
    @Override
    String tag() { return super.tag() + "B"; }
}

class Main {
    public static void main(String[] args) {
        System.out.println(new ChildTag().tag());
    }
}

class Base { String pick(int n) { return "int"; } }
class Child extends Base {
    String pick(double n) { return "double"; }
}

class Main {
    public static void main(String[] args) {
        Base b = new Child();
        System.out.println(b.pick(3));
    }
}
